const trainCategories=[{id:"express",title:"Express Trains",description:"Discover important express services connecting India's cities.",icon:"🚄"},{id:"luxury",title:"Luxury Trains",description:"Experience India's heritage through premium railway journeys.",icon:"👑"},{id:"mountain",title:"Mountain & Toy Trains",description:"Explore historic railways travelling through India's mountains.",icon:"🏔️"},{id:"heritage",title:"Heritage Trains",description:"Discover historic railway services and engineering landmarks.",icon:"🏛️"},{id:"long-distance",title:"Long-Distance Trains",description:"Explore services connecting distant regions of India.",icon:"🌏"},{id:"scenic",title:"Scenic Train Journeys",description:"Travel through some of India's most spectacular landscapes.",icon:"🌄"},{id:"modern",title:"Modern & Semi-High-Speed",description:"Discover India's modern railway technology.",icon:"⚡"},{id:"regional",title:"Regional & Special Trains",description:"Explore regional railway experiences across the country.",icon:"🚉"}],featuredTrains=[{id:"deccan-odyssey",name:"Deccan Odyssey",category:"Luxury Train",description:"A luxury tourist train exploring destinations across western India.",image:"https://images.unsplash.com/photo-1541427468627-a89a96e5ca1d?q=80&w=600&auto=format&fit=crop",path:"../deccan-odyssey-explorer/index.html"},{id:"tejas-express",name:"Tejas Express",category:"Modern Express",description:"A modern semi-high-speed fully air-conditioned train.",image:"https://images.unsplash.com/photo-1594998495048-fb9e30a5d2eb?q=80&w=600&auto=format&fit=crop",path:"../tejas-express-explorer/index.html"},{id:"humsafar-express",name:"Humsafar Express",category:"Long-Distance Express",description:"A fully premium AC-3 Tier sleeper train designed for overnight comfort.",image:"https://images.unsplash.com/photo-1563810143891-b6840742f8d8?q=80&w=600&auto=format&fit=crop",path:"../humsafar-express-explorer/index.html"},{id:"duronto-express",name:"Duronto Express",category:"Non-Stop Express",description:"Non-stop point-to-point express trains connecting major state capitals and metros.",image:"https://images.unsplash.com/photo-1601565415267-724d3d8f7b70?q=80&w=600&auto=format&fit=crop",path:"../duronto-express-explorer/index.html"}],regions=[{id:"north",name:"North India",description:"Explore railway journeys across northern India."},{id:"south",name:"South India",description:"Discover scenic routes and railway heritage in the south."},{id:"east",name:"East India",description:"Explore historic and scenic eastern railway routes."},{id:"west",name:"West India",description:"Discover desert, coastal and heritage railway journeys."},{id:"northeast",name:"Northeast India",description:"Explore railway journeys through India's northeastern landscapes."},{id:"central",name:"Central India",description:"Discover railway connections across India's heartland."}],railwayFacts=[{title:"Mountain Railways",description:"Several historic mountain railway routes form an important part of India's railway heritage and are UNESCO World Heritage Sites."},{title:"Long-Distance Connections",description:"Indian railway services connect major cities and regions across the country's diverse geography."},{title:"Railway Tourism",description:"Specialised tourist trains combine railway travel with cultural and heritage experiences, often resembling 5-star hotels on wheels."}],allTrains=[...featuredTrains,{id:"palace-on-wheels",name:"Palace on Wheels",category:"Luxury Train",description:"A luxury rail journey showcasing the heritage and landscapes of Rajasthan.",image:"https://images.unsplash.com/photo-1582293041079-7814c2f12063?q=80&w=600&auto=format&fit=crop",path:"#"},{id:"maharajas-express",name:"Maharajas' Express",category:"Luxury Train",description:"A premium railway journey through some of India's renowned cultural destinations.",image:"https://images.unsplash.com/photo-1560370487-b64ecf39ccad?q=80&w=600&auto=format&fit=crop",path:"#"},{id:"vande-bharat",name:"Vande Bharat Express",category:"Modern Express",description:"A modern semi-high-speed train series developed for intercity travel in India.",image:"https://images.unsplash.com/photo-1627918451152-4752c1e7a57c?q=80&w=600&auto=format&fit=crop",path:"#"},{id:"darjeeling-himalayan",name:"Darjeeling Himalayan Railway",category:"Mountain Railway",description:"A historic mountain railway travelling through the Himalayan foothills.",image:"https://images.unsplash.com/photo-1543789539-ff7c6b9bb7cb?q=80&w=600&auto=format&fit=crop",path:"#"}],scenicJourneys=[{name:"Darjeeling Himalayan Railway",description:"The famous 'Toy Train' winding its way through the scenic hills and tea gardens of Darjeeling.",image:"https://images.unsplash.com/photo-1543789539-ff7c6b9bb7cb?q=80&w=400&auto=format&fit=crop"},{name:"Nilgiri Mountain Railway",description:"A rack railway climbing through the Nilgiri Hills, offering breathtaking views of valleys and forests.",image:"https://images.unsplash.com/photo-1596709871181-e221d64c1c91?q=80&w=400&auto=format&fit=crop"},{name:"Kalka-Shimla Railway",description:"A narrow-gauge marvel traversing 102 tunnels to reach the summer capital of British India.",image:"https://images.unsplash.com/photo-1598282363161-0dfa0bfd2c38?q=80&w=400&auto=format&fit=crop"},{name:"Konkan Railway",description:"A coastal route between Mumbai and Mangalore featuring spectacular bridges and tunnels along the Arabian Sea.",image:"https://images.unsplash.com/photo-1601565415267-724d3d8f7b70?q=80&w=400&auto=format&fit=crop"}],heritageItems=[{title:"Mountain Railways",icon:"fa-mountain"},{title:"Steam Locomotives",icon:"fa-train-tram"},{title:"Historic Routes",icon:"fa-route"},{title:"Railway Museums",icon:"fa-building-columns"},{title:"Heritage Stations",icon:"fa-landmark"},{title:"Fairy Queen",icon:"fa-crown"}];function renderCategories(){const e=document.getElementById("categories-container");e&&(e.innerHTML=trainCategories.map(e=>`\n    <div class="category-card" tabindex="0">\n      <span class="category-icon" aria-hidden="true">${e.icon}</span>\n      <h3 class="category-title">${e.title}</h3>\n      <p class="category-desc">${e.description}</p>\n      <span class="category-link">Explore &rarr;</span>\n    </div>\n  `).join(""))}function renderFeaturedTrains(){const e=document.getElementById("featured-trains-container");e&&(e.innerHTML=featuredTrains.map(e=>`\n    <article class="featured-train-card">\n      <img src="${e.image}" alt="${e.name} train" class="featured-img" loading="lazy">\n      <div class="featured-content">\n        <p class="featured-cat">${e.category}</p>\n        <h3 class="featured-title">${e.name}</h3>\n        <p class="featured-desc">${e.description}</p>\n        <a href="${e.path}" class="explore-btn-inline">Explore &rarr;</a>\n      </div>\n    </article>\n  `).join(""))}function renderRegions(){const e=document.getElementById("regions-container");e&&(e.innerHTML=regions.map(e=>`\n    <article class="region-card" tabindex="0">\n      <h3 class="region-title">${e.name}</h3>\n      <p class="region-desc">${e.description}</p>\n    </article>\n  `).join(""))}function renderHeritage(){const e=document.getElementById("heritage-container");e&&(e.innerHTML=heritageItems.map(e=>`\n    <div class="heritage-item">\n      <i class="fa-solid ${e.icon} heritage-icon"></i>\n      <span class="heritage-title">${e.title}</span>\n    </div>\n  `).join(""))}function renderScenicJourneys(){const e=document.getElementById("scenic-container");e&&(e.innerHTML=scenicJourneys.map(e=>`\n    <div class="scenic-card">\n      <img src="${e.image}" alt="${e.name}" loading="lazy">\n      <div class="scenic-info">\n        <h4>${e.name}</h4>\n        <p>${e.description}</p>\n      </div>\n    </div>\n  `).join(""))}function renderFacts(){const e=document.getElementById("facts-container");e&&(e.innerHTML=railwayFacts.map(e=>`\n    <div class="fact-card">\n      <h4 class="fact-title">${e.title}</h4>\n      <p class="fact-desc">${e.description}</p>\n    </div>\n  `).join(""))}function renderAllTrains(){const e=document.getElementById("all-trains-container");e&&(e.innerHTML=allTrains.map(e=>`\n    <article class="featured-train-card">\n      <img src="${e.image}" alt="${e.name} train" class="featured-img" loading="lazy">\n      <div class="featured-content">\n        <p class="featured-cat">${e.category}</p>\n        <h3 class="featured-title">${e.name}</h3>\n        <p class="featured-desc">${e.description}</p>\n        <a href="${e.path}" class="explore-btn-inline">Explore &rarr;</a>\n      </div>\n    </article>\n  `).join(""))}document.addEventListener("DOMContentLoaded",()=>{renderCategories(),renderFeaturedTrains(),renderRegions(),renderHeritage(),renderScenicJourneys(),renderFacts(),renderAllTrains()});